  busy=true;error='';draw();
  try{const result=await api(`sessions/${id}/generate`,{requestId:uuid(),revision:session.canvas.revision,brief,wardrobe:[...inventory(),...session.canvas.items.filter(i=>i.ownership==='user-described')]},'POST',event=>{if(event.type==='draft'&&session.id===id&&!editor.pending&&event.session.canvas.revision>=session.canvas.revision){session=event.session;provisional=true;draw();}});provisional=false;if(session.id===id){if(editor.pending||result.canvas.revision<session.canvas.revision)throw Object.assign(new Error('Your newer Canvas edits are kept. Request fresh suggestions when saving finishes.'),{status:409});session=result;draftBrief={...result.canvas.brief,request:''};remember();if(canvasOpen&&session.looks[0]){await mutate('select',{lookId:session.looks[0].id});announce('The first styling option is in Canvas. Back to conversation shows all alternatives.');}}}
  finally{busy=false;draw();}
